code_example:
#include <iostream>

template <template <class> class T>
class A {
public:
    inline void f();
};

template <template <class> class T>
inline void A<T>::f()() {
    std::cout << "Template member function specialized for template class" << std::endl;
}

int main() {
    A<std::vector> a;
    a.f();
    return 0;
}
